mapper.select:
SELECT l.* FROM promotion_link l
JOIN short_drama_connection c ON c.id = l.connection_id
JOIN provider_drama d ON d.id = l.drama_id
JOIN promotion_user u ON u.id = l.user_id
WHERE l.status = 'SUCCESS'
  AND l.connection_id = #{connectionId}
  AND c.partner_id = #{partnerId}
  AND d.external_drama_id = #{externalDramaId}
  AND u.user_no = #{userNo}
  AND l.external_code = #{externalCode}
ORDER BY l.id
LIMIT 1

SELECT * FROM promotion_link
WHERE status = 'SUCCESS'
  AND connection_id = #{connectionId}
  AND drama_id = #{dramaId}
  AND user_id = #{userId}
  AND external_code = #{externalCode}
ORDER BY id
LIMIT 1

mapper.update:
UPDATE promotion_link SET status = 'SUCCESS', external_code = #{externalCode}, share_url = #{shareUrl},
    last_error_code = NULL, last_error_message = NULL,
    updated_at = CURRENT_TIMESTAMP WHERE id = #{id}
